internal fun playlistImportHubLocalizationCodes(): Set<String> = playlistImportHubBundles.keys

internal fun playlistImportHubLocalizationEntries(code: String): Map<String, String> {
    val raw = localizedValueOrEnglish(playlistImportHubBundles, code)
    val values = raw.split('|')
    return playlistImportHubKeys.withIndex().associate { (index, key) -> key to values.getOrElse(index) { "" } }
}

class PlaylistImportHubCopy internal constructor(private val entries: Map<String, String>) {
    operator fun get(key: String): String = entries[key].orEmpty()

    fun format(key: String, vararg values: Pair<String, Any>): String =
        values.fold(get(key)) { text, (name, value) -> text.replace("{$name}", value.toString()) }

    val changeMatchConflict: String
        get() = get("changeMatchConflict")
}

private val playlistImportHubCache = java.util.concurrent.ConcurrentHashMap<String, PlaylistImportHubCopy>()

fun playlistImportHubCopy(code: String): PlaylistImportHubCopy =
    playlistImportHubCache.getOrPut(code) { PlaylistImportHubCopy(playlistImportHubLocalizationEntries(code)) }
